INSERT INTO plans (date, praise_scope, praise_content, devotional_scope, church_prayer_scripture, church_prayer_guide) VALUES
  ('2026-10-01', '詩篇 92:1', '稱謝耶和華，歌頌至高者的名是美好的。', '耶利米書 第 50 章,民數記 第 16 章', '「凡敬畏神的人，你們都來聽！我要述說他為我所行的事。」詩篇 66:16', '為教會中那些經歷生命突破、關係修復、甚至勇敢面對自我挑戰的見證感恩。因為這些生命改變的奇蹟，都是榮耀神的記號。'),
  ('2026-10-02', '啟示錄 19:1', '讚美你們的上帝！拯救、榮耀和權能都屬於我們的上帝！', '耶利米書 第 51 章,民數記 第 17 章', '「又要彼此相顧，激發愛心，勉勵行善。」希伯來書 10:24', '感謝神賜下屬靈同伴與肢體。為著那些在小組與服事團隊中願意對我們說真話、挑戰我們生命成長、陪伴我們度過低潮的屬靈家人獻上感謝。'),
  ('2026-10-03', '詩篇 138:8', '耶和華必為我成就祂的旨意。耶和華啊，你的慈愛永遠長存。', '耶利米書 第 52 章,民數記 第 18 章', '「你以恩典為年歲的冠冕；你的路徑都滴下脂油。」詩篇 65:11', '為教會現有的場地與過去神一切的供應感恩。讚美神在每個季節都賜下夠用的恩典與豐盛的資源。'),
  ('2026-10-04', '以賽亞書 55:9', '天怎樣高過地，我的道路也怎樣高過你們的道路，我的意念也怎樣高過你們的意念。', '耶利米哀歌 第 1 章,民數記 第 19 章', '「流淚撒種的，必歡呼收割！那帶種流淚出去的，必要歡歡樂樂地帶禾捆回來！」詩篇 126:5-6', '為著在家庭與職場福音工作中感到挫折的人禱告，相信我們為家人和朋友流淚的代求，必會迎來他們信主受洗的歡呼！'),
  ('2026-10-05', '詩篇 47:7', '因為上帝是全地的王，你們要用詩歌讚美祂。', '耶利米哀歌 第 2 章,民數記 第 20 章', '「我是大有憂愁，心裡時常傷痛；為我弟兄，我骨肉之親，就是自己被咒詛，我也願意。」羅馬書 9:2-3', '求神把保羅那種對骨肉之親靈魂得救的「迫切渴望」放在我們裡面。在禱告中呼求未信主家人的名字，不再對他們的得救感到麻木。'),
  ('2026-10-06', '馬可福音 10:27', '在人不能，在上帝凡事都能。', '耶利米哀歌 第 3 章,民數記 第 21 章', '「他們說：當信主耶穌，你和你一家都必得救。」使徒行傳 16:31', '抓住神對家庭的應許！宣告我們的家人都在神的救恩計畫中，求神預備他們的心，也賜給我們智慧與好品格，在家中成為美好的見證。'),
  ('2026-10-07', '詩篇 145:13', '你的國度是永遠的國度，你的王權存到萬代。', '耶利米哀歌 第 4 章,民數記 第 22 章', '「你們是世上的光...你們的光也當這樣照在人前，叫他們看見你們的好行為，便將榮耀歸給你們在天上的父。」馬太福音 5:14-16', '為我們的職場與學校生活禱告。求神幫助我們在工作／學業、承擔責任與人際關係上活出基督的樣式，讓身邊的人透過我們看見基督的光。'),
  ('2026-10-08', '以賽亞書 43:10', '我是耶和華，在我以前沒有上帝，在我以後也絕不會有。', '耶利米哀歌 第 5 章,民數記 第 23 章', '「向軟弱的人，我就作軟弱的人，為要得軟弱的人。向甚麼樣的人，我就作甚麼樣的人。無論如何，總要救些人。」哥林多前書 9:22', '求神給我們同理心與智慧，能用同事、朋友聽得懂的語言和方式來關心他們，建立真實的友誼。'),
  ('2026-10-09', '詩篇 90:1', '主啊，你是我們世世代代的居所。', '以西結書 第 1 章,民數記 第 24 章', '「也為我祈求，使我得著口才，能以放膽開口講明福音的奧祕。」以弗所書 6:19', '求聖靈賜下膽量，幫助我們克服在生活圈中傳福音、甚至被拒絕的恐懼。當同事或朋友遇到困難低潮時，我們能勇敢開口為他們禱告。'),
  ('2026-10-10', '約翰福音 4:24', '上帝是靈，敬拜祂的人必須用心靈按真理敬拜祂。', '以西結書 第 2 章,民數記 第 25 章', '「就對他們說：要收的莊稼多，做工的人少。所以，你們當求莊稼的主打發工人出去收他的莊稼。」路加福音 10:2', '求神幫助我們看見每天通勤、辦公、吃飯的地方，就是充滿莊稼的禾場。回應神的呼召：「我」就是那個「去」收割的工人。'),
  ('2026-10-11', '詩篇 147:4', '祂數點星辰的數目，一一稱它們的名字。', '以西結書 第 3 章,民數記 第 26 章', '「這殿後來的榮耀必大過先前的榮耀；在這地方我必賜平安。這是萬軍之耶和華說的。」哈該書 2:9', '帶著極大的期待進入主日敬拜，教會要充滿神的同在與榮耀，成為許多失喪靈魂遇見神、得著平安的家。'),
  ('2026-10-12', '以賽亞書 46:4', '我直到你們年老，仍這樣待你們，直到你們髮白，仍背負你們。', '以西結書 第 4 章,民數記 第 27 章', '「要擴張你帳幕之地，張大你居所的幔子，不要限制；要放長你的繩子，堅固你的橛子。」以賽亞書 54:2', '明年的搬遷與擴張是神為了 Baptize Taiwan 預備的「新皮袋」，求神幫助我們的眼光和心思也跟著一起擴大，跟上神的工作。'),
  ('2026-10-13', '詩篇 97:9', '耶和華啊，你在全地上至高無上，你超越一切假神。', '以西結書 第 5 章,民數記 第 28 章', '「因為我們是與神同工的；你們是神所耕種的田地，所建造的房屋。」哥林多前書 3:9', '宣告每一位會眾都是教會建造的參與者。求神感動我們在奉獻、各項服事上全力以赴，齊心預備好與神一起 Baptize Taiwan。'),
  ('2026-10-14', '羅馬書 11:36', '因為萬物都源於祂，藉著祂，歸於祂。願榮耀歸給祂，直到永遠！阿們！', '以西結書 第 6 章,民數記 第 29 章', '「你當剛強壯膽！不要懼怕，也不要驚惶；因為你無論往哪裡去，耶和華你的神必與你同在。」約書亞記 1:9', '求神給予我們信心取代對於面對搬遷、距離變動或未知挑戰的擔憂，相信神的同在會一路引導教會的腳步。'),
  ('2026-10-15', '詩篇 111:7', '祂憑信實和公正行事，祂一切的法則都可靠。', '以西結書 第 7 章,民數記 第 30 章', '「我的神必照他榮耀的豐富，在基督耶穌裡，使你們一切所需用的都充足。」腓立比書 4:19', '為接下來教會一切的需求守望，宣告耶和華以勒的神，必豐豐富富地供應教會一切所需。'),
  ('2026-10-16', '以弗所書 3:20', '上帝能照著運行在我們裡面的大能，成就一切，遠遠超過我們所求所想的。', '以西結書 第 8 章,民數記 第 31 章', '「只要你們行事為人與基督的福音相稱...知道你們同有一個心志，站立得穩，為所信的福音齊心努力。」腓立比書 1:27', '在轉換的季節中，求神保守各團隊的合一與穩定。讓我們不為硬體與流程的變動抱怨，而是為著「回應大使命」的目標互相幫補，同心努力。'),
  ('2026-10-17', '詩篇 7:17', '我要稱謝耶和華的公義，歌頌至高者耶和華的名。', '以西結書 第 9 章,民數記 第 32 章', '「你們要互相款待，不發怨言。各人要照所得的恩賜彼此服事，作神百般恩賜的好管家。」彼得前書 4:9-10', '為所有前線團隊（招待、敬拜、兒童、技術等）禱告。當我們進入新場地、面對更多慕道友時，能帶著極大的愛心與卓越來款待人。'),
  ('2026-10-18', '約翰福音 14:6', '耶穌說：「我就是道路、真理、生命；若不藉著我，沒有人能到父那裡去。」', '以西結書 第 10 章,民數記 第 33 章', '「因為萬有都是本於他，倚靠他，歸於他。願榮耀歸給他，直到永遠。阿們！」羅馬書 11:36', '帶著敬畏的心進入主日，將明年的 Baptize Taiwan 完全獻給神。一切都是為了神的榮耀，我們準備好出發了！'),
  ('2026-10-19', '詩篇 103:2', '我的心哪，你要稱頌耶和華，不可忘記祂的一切恩惠。', '以西結書 第 11 章,民數記 第 34 章', '「我又聽見主的聲音說：我可以差遣誰呢？誰肯為我們去呢？我說：我在這裡，請差遣我！」以賽亞書 6:8', '勇敢回應神的呼召！傳福音不只是教會的計畫，也是耶穌給我的大使命。求神差遣我們成為 Baptize Taiwan 的福音使者。'),
  ('2026-10-20', '以賽亞書 30:18', '耶和華渴望恩待你們，祂必興起憐憫你們。', '以西結書 第 12 章,民數記 第 35 章', '「你求我，我就將列國賜你為基業，將地極賜你為田產。」詩篇 2:8', '擴大我們的禱告視野，為台灣各個城市、鄉鎮，與偏鄉呼求。'),
  ('2026-10-21', '詩篇 148:5', '願這些都讚美耶和華的名，因為祂一發令，它們就被創造。', '以西結書 第 13 章,民數記 第 36 章', '「我們爭戰的兵器本不是屬血氣的，乃是在神面前有能力，可以攻破堅固的營壘。」哥林多後書 10:4', '為台灣各地的屬靈空氣禱告，求聖靈敲打各地傳統信仰、人心冷漠與絕望的堅固營壘，讓真理的光照進每一個角落。'),
  ('2026-10-22', '以賽亞書 40:15', '看啊，萬民在祂眼中如水桶裡的一滴水，又像天平上的一粒塵土。', '以西結書 第 14 章,申命記 第 1 章', '「主對我說：人子啊，你要發預言...氣息就進入骸骨，骸骨便活了，並且站起來，成為極大的軍隊。」以西結書 37:9-10', '宣告聖靈的風要吹進台灣！吹進每一個被罪轄制、被憂鬱綑綁的靈魂裡，讓絕望的世代活過來，成為屬神的子民。'),
  ('2026-10-23', '詩篇 104:24', '耶和華啊，你所造的何其多，你以智慧創造了這一切！', '以西結書 第 15 章,申命記 第 2 章', '「我不但為這些人祈求，也為那些因他們的話信我的人祈求，使他們都合而為一...叫世人可以信你差了我來。」約翰福音 17:20-21', '為全台灣的眾教會禱告。求神打破宗派與地域的隔閡，讓台灣的教會能真實合一，帶出榮耀神的見證。'),
  ('2026-10-24', '羅馬書 1:20', '自從創世以來，上帝那看不見的特質，就是祂永恆的大能和神性，都藉著受造物清楚地顯明出來。', '以西結書 第 16 章,申命記 第 3 章', '「此後，我觀看，見有許多的人，沒有人能數過來，是從各國、各族、各民、各方來的，站在寶座和羔羊面前...」啟示錄 7:9', '閉上眼睛，想像明年的 Baptize Taiwan 會帶來什麼樣的光景。宣告將有數不清的台灣人，與我們一起站在寶座前敬拜神。'),
  ('2026-10-25', '詩篇 57:11', '上帝啊，願你被高舉，超越諸天，願你的榮耀遍滿全地！', '以西結書 第 17 章,申命記 第 4 章', '「我們要因你的救恩誇勝，要奉我們神的名設立旌旗。願耶和華成就你一切所求的！」詩篇 20:5', '高舉得勝的旌旗！宣告神要在台灣各地做成祂要做的工作，使祂的榮耀被看見。'),
  ('2026-10-26', '以賽亞書 26:4', '要永遠信靠耶和華，因為耶和華是永遠屹立的磐石。', '以西結書 第 18 章,申命記 第 5 章', '「約書亞吩咐百姓說：你們要自潔，因為明天耶和華必在你們中間行奇事。」約書亞記 3:5', '預備好我們的生命與態度。宣告我們不再停留在過去的框架裡，因為神即將在我們的教會與台灣以及我和我的家庭中施行奇妙的大事。'),
  ('2026-10-27', '詩篇 46:1', '上帝是我們的避難所和力量，是我們患難中隨時的幫助。', '以西結書 第 19 章,申命記 第 6 章', '「你所做的，要交託耶和華，你所謀的，就必成立。」箴言 16:3', '為著我們所踏出的每一個腳步，手所作的每一件事都交在上帝的手中禱告。'),
  ('2026-10-28', '哥林多前書 10:26', '因為「地和地上的一切都是主的。」', '以西結書 第 20 章,申命記 第 7 章', '「我告訴他們我神施恩的手怎樣幫助我...他們就說：我們起來建造吧！於是他們奮勇做這善工。」尼希米記 2:18', '求神激發全體會眾的熱情！讓每一個人都不做旁觀者，而是同心奮勇起來，在未來的各項行動中成為建造的一份子。'),
  ('2026-10-29', '詩篇 19:1', '諸天訴說上帝的榮耀，穹蒼傳揚祂的手段。', '以西結書 第 21 章,申命記 第 8 章', '「信就是所望之事的實底，是未見之事的確據。」希伯來書 11:1', '在尚未看見的時候，求神賜給我們不動搖的信心，持續忠心的做祂要我們做的事，因祂的應許就是我的盼望。'),
  ('2026-10-30', '啟示錄 7:12', '願頌讚、榮耀、智慧、感謝、尊貴、權柄、能力都歸給我們的上帝，直到永永遠遠。阿們！', '以西結書 第 22 章,申命記 第 9 章', '「願主─我們神的榮美歸於我們身上。願你堅立我們手所做的工；我們手所做的工，願你堅立！」詩篇 90:17', '將所有 THE HOPE 家人的擺上、未信主家人的名單，以及台灣的未來獻給神。願主的榮美歸於我們，堅立我們手所做的工！'),
  ('2026-10-31', '詩篇 115:3', '我們的上帝在天上，祂隨自己的意旨行事。', '以西結書 第 23 章,申命記 第 10 章', '「興起，發光！因為你的光已經來到！耶和華的榮耀發現照耀你。」以賽亞書 60:1', '為這充滿突破與預備的一個月獻上感恩！宣告教會全體要興起發光，帶著極大的信心與神同在的榮耀。')
